// Generate Markdown docs for field-input options from Zod schemas via z.toJSONSchema().
// Runs after gen-resource-schema.mjs (same tsup onSuccess chain), imports from ../dist/index.js.
// Writes docs/guide/2.resources/field-inputs/_generated/<schemaFile>.md (committed, drift-checked).
// --ci flag: exits 1 if any generated file differs from what's on disk (for local drift checks).
import { z } from 'zod';
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const CI_MODE = process.argv.includes('--ci');

import { BaseOptionsSchema, fieldInputRegistry } from '../dist/index.js';

const here = dirname(fileURLToPath(import.meta.url));
const pkgRoot = join(here, '..');
const repoRoot = join(pkgRoot, '..', '..');
const docsGeneratedDir = join(
  repoRoot,
  'docs',
  'guide',
  '2.resources',
  'field-inputs',
  '_generated',
);

const baseKeys = new Set(Object.keys(BaseOptionsSchema.shape));

// Build reverse map: schemaFile → [registered type keys]
const aliasMap = new Map();
for (const [type, def] of fieldInputRegistry) {
  const arr = aliasMap.get(def.schemaFile) ?? [];
  arr.push(type);
  aliasMap.set(def.schemaFile, arr);
}

const formatType = (prop) => {
  if (!prop || Object.keys(prop).length === 0) return 'any';
  if (prop.type === 'array') {
    const item = prop.items ? formatType(prop.items) : 'unknown';
    return `${item}[]`;
  }
  if (prop.type === 'object' || prop.additionalProperties !== undefined) return 'object';
  if (prop.type) return prop.type;
  if (prop.enum) return prop.enum.map((v) => `"${v}"`).join(' \\| ');
  if (prop.anyOf) {
    const parts = prop.anyOf.map(formatType).filter((t) => t !== 'null' && t !== 'any');
    return parts.length ? parts.join(' \\| ') : 'any';
  }
  if (prop.const !== undefined) return `"${prop.const}"`;
  return 'any';
};

const HEADER = '| Option | Type | Required | Default | Description | Example |\n|--------|------|----------|---------|-------------|---------|';

const propRow = (key, prop, required = []) => {
  const type = formatType(prop);
  const isRequired = required.includes(key) ? 'Yes' : 'No';
  const def = prop.default !== undefined ? `\`${JSON.stringify(prop.default)}\`` : '';
  const desc = prop.description ?? '';
  const ex = Array.isArray(prop.examples) && prop.examples.length
    ? prop.examples.map((e) => `\`${JSON.stringify(e)}\``).join(', ')
    : '';
  return `| \`${key}\` | ${type} | ${isRequired} | ${def} | ${desc} | ${ex} |`;
};

const renderTable = (properties, required = [], filterFn = () => true) => {
  const rows = Object.entries(properties)
    .filter(([k]) => filterFn(k))
    .map(([k, p]) => propRow(k, p, required));
  if (!rows.length) return null;
  return `${HEADER}\n${rows.join('\n')}`;
};

const GENERATED_COMMENT = '<!-- generated by gen-field-input-docs.mjs — do not edit -->\n\n';

const generateBaseDoc = () => {
  const jsonSchema = z.toJSONSchema(BaseOptionsSchema, {
    target: 'draft-7',
    io: 'input',
    unrepresentable: 'any',
  });
  const props = jsonSchema.properties ?? {};
  const req = jsonSchema.required ?? [];
  const table = renderTable(props, req, (k) => baseKeys.has(k));
  return `${GENERATED_COMMENT}${table ?? '_No properties_'}\n`;
};

const generateTypeDoc = (schemaFile, def) => {
  const aliases = aliasMap.get(schemaFile) ?? [];
  const typeLine = `**Used by:** ${aliases.map((t) => `\`${t}\``).join(', ')}\n`;

  let jsonSchema;
  try {
    jsonSchema = z.toJSONSchema(def.options, {
      target: 'draft-7',
      io: 'input',
      unrepresentable: 'any',
    });
  } catch {
    return `${GENERATED_COMMENT}${typeLine}\n_Could not generate schema._\n`;
  }

  // Union schema (e.g. autocomplete)
  if (Array.isArray(jsonSchema.anyOf)) {
    const shownKeys = new Set();
    const sections = jsonSchema.anyOf
      .filter((v) => v.type === 'object' && v.properties)
      .map((variant) => {
        const ownKeys = Object.keys(variant.properties).filter((k) => !baseKeys.has(k));
        const newKeys = ownKeys.filter((k) => !shownKeys.has(k));
        // Skip variant if it introduces no new properties (pure subset already shown)
        if (!newKeys.length) return null;
        newKeys.forEach((k) => shownKeys.add(k));
        const title = variant.title ? `### ${variant.title}` : '';
        const table = renderTable(
          variant.properties,
          variant.required ?? [],
          (k) => !baseKeys.has(k),
        );
        if (!table) return null;
        return [title, '', table].filter(Boolean).join('\n');
      })
      .filter(Boolean);

    if (!sections.length) {
      return `${GENERATED_COMMENT}${typeLine}\n_All common options apply; no type-specific options._\n`;
    }
    return `${GENERATED_COMMENT}${typeLine}\n**Also available:** all [common options](../common-options.md).\n\n${sections.join('\n\n')}\n`;
  }

  // Regular object schema
  const props = jsonSchema.properties ?? {};
  const req = jsonSchema.required ?? [];
  const table = renderTable(props, req, (k) => !baseKeys.has(k));

  if (!table) {
    return `${GENERATED_COMMENT}${typeLine}\n_All common options apply; no type-specific options._\n`;
  }
  return `${GENERATED_COMMENT}${typeLine}\n**Also available:** all [common options](../common-options.md).\n\n${table}\n`;
};

const inRepoWithDocs = existsSync(join(repoRoot, 'docs', '.vuepress'));
if (!inRepoWithDocs) {
  console.info('[crouton-core] no docs dir found, skipping field-input docs generation');
  process.exit(0);
}

mkdirSync(docsGeneratedDir, { recursive: true });

const writes = new Map();
writes.set(join(docsGeneratedDir, 'base.md'), generateBaseDoc());

const emitted = new Set();
for (const [_type, def] of fieldInputRegistry) {
  if (emitted.has(def.schemaFile)) continue;
  emitted.add(def.schemaFile);
  writes.set(join(docsGeneratedDir, `${def.schemaFile}.md`), generateTypeDoc(def.schemaFile, def));
}

let drifted = [];
for (const [filePath, content] of writes) {
  if (CI_MODE) {
    const existing = existsSync(filePath) ? readFileSync(filePath, 'utf8') : null;
    if (existing !== content) drifted.push(filePath);
  }
  writeFileSync(filePath, content);
}

if (CI_MODE && drifted.length > 0) {
  console.error(
    `[crouton-core] --ci: ${drifted.length} file(s) are out of date:\n${drifted.map((f) => `  ${f}`).join('\n')}`,
  );
  console.error('Run pnpm nx run crouton-core:build to regenerate.');
  process.exit(1);
}

console.info(
  `[crouton-core] wrote _generated/base.md + ${emitted.size} field-input doc files`,
);
